import React, { useState, useEffect } from 'react';
import './IQ.css';
import IQ_HomeGrid from './IQ_HomeGrid';
import IQ_MusicWidget from './IQ_MusicWidget';
import IQ_MediaApp from './apps/IQ_MediaApp'; // Import the new functional app
import { Wind, Wifi, Home, Grid } from 'react-feather';

// --- Placeholder App Components ---
const NavigationApp = () => <div className="iq-app-placeholder"><h1>Navigation</h1></div>;
const PhoneApp = () => <div className="iq-app-placeholder"><h1>Phone</h1></div>;
const SettingsApp = () => <div className="iq-app-placeholder"><h1>Settings</h1></div>;
const ClimateApp = () => <div className="iq-app-placeholder"><h1>Climate</h1></div>;

const IQ_ConsoleTablet = () => {
    const [activeView, setActiveView] = useState('Home'); 
    const [nowPlaying, setNowPlaying] = useState({
        title: 'Starlight',
        artist: 'Muse',
        albumArtUrl: 'https://upload.wikimedia.org/wikipedia/en/thumb/e/e9/Muse_Starlight.jpg/220px-Muse_Starlight.jpg',
        isPlaying: false,
        progress: 30, // Percentage
    });

    // This is where the app components are registered
    const appRegistry = {
        'Navigation': NavigationApp,
        'Media': () => <IQ_MediaApp nowPlaying={nowPlaying} onPlayPause={handlePlayPause} onNext={handleNext} onPrev={handlePrev} />,
        'Phone': PhoneApp,
        'Settings': SettingsApp,
        'Climate': ClimateApp,
    };

    // --- Media Control Logic ---
    const handlePlayPause = (shouldPlay) => {
        setNowPlaying(prev => ({ ...prev, isPlaying: shouldPlay }));
        // When we play, show the AR view
        if (shouldPlay) {
            const message = {
                iq_sender: 'console',
                type: 'iq-ar-update',
                payload: { type: 'media', ...nowPlaying }
            };
            window.parent.postMessage(message, '*');
        }
    };

    const handleNext = () => console.log("Next track"); // Placeholder
    const handlePrev = () => console.log("Previous track"); // Placeholder

    // --- Main Renderer ---
    const renderMainContent = () => {
        if (activeView === 'Home') {
            return <IQ_HomeGrid onAppClick={setActiveView} />;
        }
        const ActiveAppComponent = appRegistry[activeView];
        return ActiveAppComponent ? ActiveAppComponent() : <IQ_HomeGrid onAppClick={setActiveView} />;
    };

    return (
        <div className="iq-component iq-console">
            <div className="iq-console-statusbar">
                <div className="status-left"><Wind size={20} /> 72°</div>
                <div className="status-right"><Wifi size={20} /> 5G</div>
            </div>

            <div className="iq-console-main-content">
                {renderMainContent()}
            </div>

            <div className="iq-console-dock">
                <div className="dock-nav-buttons">
                    <button className={activeView === 'Home' ? 'active' : ''} onClick={() => setActiveView('Home')}>
                        <Home size={28} />
                    </button>
                    <button><Grid size={28} /></button>
                </div>
                <div className="dock-music-widget-container">
                    <IQ_MusicWidget nowPlaying={nowPlaying} onPlayPause={handlePlayPause} />
                </div>
            </div>
        </div>
    );
};

export default IQ_ConsoleTablet;
